CREATE TABLE Bus_Route (
    Destination VARCHAR(255),
    Passing_Stations VARCHAR(255),
    Route_ID INTEGER PRIMARY KEY,
    Starting_Point VARCHAR(255)
);

CREATE TABLE Bus (
    Vehicle_ID INTEGER PRIMARY KEY,
    Vehicle_Status VARCHAR(255),
    Vehicle_Type VARCHAR(255)
);

CREATE TABLE Employee (
    Contact_Information VARCHAR(255),
    Employee_ID INTEGER PRIMARY KEY,
    ID_Number VARCHAR(255),
    Name VARCHAR(255),
    Position VARCHAR(255)
);

CREATE TABLE Announcement (
    Announcement_Content VARCHAR(255),
    Announcement_ID INTEGER PRIMARY KEY,
    Announcement_Title VARCHAR(255),
    Release_Time DATETIME
);

CREATE TABLE Passenger (
    Contact_Information VARCHAR(255),
    Name VARCHAR(255),
    Registration_Information VARCHAR(255),
    User_ID INTEGER PRIMARY KEY
);

CREATE TABLE Dispatch_Route_Arrangement (
    Dispatch_Task_ID INTEGER PRIMARY KEY,
    Route_ID INTEGER NOT NULL,
    FOREIGN KEY (Route_ID) REFERENCES Bus_Route(Route_ID)
);

CREATE TABLE Dispatch_Vehicle_Arrangement (
    Dispatch_Task_ID INTEGER PRIMARY KEY,
    Vehicle_ID INTEGER NOT NULL,
    FOREIGN KEY (Vehicle_ID) REFERENCES Bus(Vehicle_ID)
);

CREATE TABLE Dispatch_Employee_Arrangement (
    Dispatch_Task_ID INTEGER PRIMARY KEY,
    Employee_ID INTEGER NOT NULL,
    FOREIGN KEY (Employee_ID) REFERENCES Employee(Employee_ID)
);
